function updateStairWalk(){let inside=p.x<1.6&&p.z>=9&&p.z<=20;if(!inside){p.stairY=0;stairRun=null;return}if(p.z>=17){if(stairRun){floor=p.x<-4.7?stairRun.base:stairRun.base+1;floor=Math.max(0,Math.min(3,floor));notify(floorName(floor)+' 계단참');stairRun=null;navClock=0;}p.stairY=0;return}if(!stairRun){let base=p.x<-4.7?floor:floor-1;if(base<0||base>2)return;stairRun={base};}let y;if(p.z<=11)y=stairRun.base*4.2+2.1;else if(p.x<-4.7)y=stairRun.base*4.2+(17-p.z)*.35;else y=stairRun.base*4.2+2.1+(p.z-11)*.35;p.stairY=y-floor*4.2;}
