const shadedTiles=new Map();
function shadedTile(tx,ty,color,shade){let level=Math.max(0,Math.min(12,Math.round(shade*12))),key=tx+','+ty+':'+color.join(',')+':'+level;if(shadedTiles.has(key))return shadedTiles.get(key);let tile=document.createElement('canvas');tile.width=tile.height=256;let ctx=tile.getContext('2d');ctx.drawImage(atlas,tx*256,ty*256,256,256,0,0,256,256);ctx.globalCompositeOperation='multiply';ctx.fillStyle='rgb('+color.map(c=>Math.round(c*level/12*255)).join(',')+')';ctx.fillRect(0,0,256,256);ctx.globalCompositeOperation='source-over';if(shadedTiles.size>=96)shadedTiles.delete(shadedTiles.keys().next().value);shadedTiles.set(key,tile);return tile}
function drawAffine(g,a,b,c,color,shade){let mx=(a[0]+b[0]+c[0])/3,my=(a[1]+b[1]+c[1])/3,expand=v=>{let d=Math.max(1,Math.hypot(v[0]-mx,v[1]-my));return[v[0]+(v[0]-mx)/d*.65,v[1]+(v[1]-my)/d*.65,...v.slice(2)]};a=expand(a);b=expand(b);c=expand(c);let u0=a[2],v0=a[3],u1=b[2],v1=b[3],u2=c[2],v2=c[3],den=u0*(v1-v2)+u1*(v2-v0)+u2*(v0-v1);if(Math.abs(den)<.01)return;let ax=(a[0]*(v1-v2)+b[0]*(v2-v0)+c[0]*(v0-v1))/den,bx=(a[1]*(v1-v2)+b[1]*(v2-v0)+c[1]*(v0-v1))/den,cy=(a[0]*(u2-u1)+b[0]*(u0-u2)+c[0]*(u1-u0))/den,dy=(a[1]*(u2-u1)+b[1]*(u0-u2)+c[1]*(u1-u0))/den,ex=(a[0]*(u1*v2-u2*v1)+b[0]*(u2*v0-u0*v2)+c[0]*(u0*v1-u1*v0))/den,fy=(a[1]*(u1*v2-u2*v1)+b[1]*(u2*v0-u0*v2)+c[1]*(u0*v1-u1*v0))/den;g.save();g.beginPath();g.moveTo(a[0],a[1]);g.lineTo(b[0],b[1]);g.lineTo(c[0],c[1]);g.closePath();g.clip();g.setTransform(ax,bx,cy,dy,ex,fy);let tx=Math.min(7,Math.floor((a[2]+b[2]+c[2])/3/256)),ty=Math.min(7,Math.floor((a[3]+b[3]+c[3])/3/256));g.drawImage(shadedTile(tx,ty,color,shade),tx*256,ty*256);g.restore()}

for(const event of ["gesturestart","gesturechange","gestureend","dblclick"])document.addEventListener(event,e=>e.preventDefault(),{passive:false});
document.addEventListener("touchstart",e=>{if(e.touches.length>1)e.preventDefault()},{passive:false});


function canApplyGameUpdate(){return state==='menu'}

